import{_ as i,l as d,o as a,c as s,v as o,p as l,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"文件作为字节流","description":"","frontmatter":{"title":"文件作为字节流","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/file-bytestream.md","filePath":"cs/file-bytestream.md","lastUpdated":1789023840000}'),m={name:"cs/file-bytestream.md"};function h(_,e,E,f,u,B){const r=d("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="文件作为字节流" tabindex="-1">文件作为字节流 <a class="header-anchor" href="#文件作为字节流" aria-label="Permalink to &quot;文件作为字节流&quot;">​</a></h1><div class="epigraph"><p>Unix 文件是无结构的字节序列；记录格式属于用户程序，不属于内核。</p><footer>—— 据 Ritchie and Thompson, The UNIX Time-Sharing System, 1974 整理</footer></div><p><a href="/cs/memory-reclaim">上一课</a>已经能把某段字节接到虚地址，但「文件」还只是映射的后端。<a href="/cs/syscall-path">系统调用路径</a>上的 <code>read</code>/<code>write</code> 需要一个与页表无关的对象：打开实例、偏移、可读可写。缺口是把文件定义为<strong>字节流</strong>，目录与 inode 仍未展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若内核坚持记录式文件（固定字段），管道和设备套不进去。Unix 的选择：文件是线性字节，位置由打开文件描述（偏移）记住。同一磁盘 inode 可被多次打开，各有各的偏移。缺口不是磁盘调度，而是用户看见的抽象：描述符、流、阻塞直到有数据——与<a href="/cs/ipc-pipe">管道</a>同一接口。</p><p>本课不把「一切皆文件」扩到 epoll 的全部历史。</p><p><span class="marginnote">描述符是进程映像里的整数索引。fork 复制表；exec 可保留。偏移在 <em>打开文件</em> 对象上，所以 dup 的两个描述符共享偏移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open</code> 把路径解析成内核文件对象（下一课 inode），在 PCB 描述符表里占一槽，偏移为零（或追加）。<code>read</code>/<code>write</code> 按偏移搬字节，更新偏移。<code>lseek</code> 改偏移但不搬。管道与套接字也是描述符，只是没有可 seek 的线性介质。mmap 是同一文件对象的另一视图。</p>',9)),(a(),l(p,null,{default:t(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20OPEN%5B%22%E6%89%93%E5%BC%80%E6%96%87%E4%BB%B6%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20OPEN%20--%3E%20FD%5B%22%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20FD%20--%3E%20RW%5B%22read%2Fwrite%20%E6%8C%89%E5%81%8F%E7%A7%BB%22%5D%0A%20%20FD%20--%3E%20MM%5B%22mmap%20%E8%A7%86%E5%9B%BE%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>字节流让管道、文件、后来的套接字共用一套系统调用，用户程序可以重定向标准输入而不重编译。结构化记录（数据库页）在用户或后课数据库栏自己做；OS 主干不把关系模型请进来。阻塞语义接调度：没有字节就睡，写者或磁盘完成再醒。</p><p>与 mmap 的差别：<code>read</code> 的错误是返回值；拷贝进用户缓冲，不暴露页 Cache 的虚地址。两种接口对着同一持久字节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入记录锁定的全部 POSIX 细节，不把 Windows 的 HANDLE 当另一套理论。也不讲文本与二进制在内核里的差别：Unix 内核不做 CRLF 翻译。路径如何变成编号，下一课 inode 与目录。</p><p><code>pread</code>/<code>pwrite</code> 不移动共享偏移，给线程共用一个描述符时少一种竞态；偏移仍是打开文件的属性。</p><p>后课默认：用户通过描述符看见字节流。名字与元数据落在 inode 与目录里，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文件是无结构字节序列；记录是用户的事。</li><li>描述符指向打开实例；偏移在打开文件上。</li><li>路径解析与 inode 是下一课。</li><li>出处：Ritchie and Thompson, <em>CACM</em> 1974；Tanenbaum <em>MOS</em>。</li></ul>',9))])}const b=i(m,[["render",h]]);export{T as __pageData,b as default};
